import{z as l,x as s,o as B,c as d,q as i,j as o,D as a,d as e,s as r,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"流动性的共同因子","description":"","frontmatter":{"title":"流动性的共同因子","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-liquidity-common-factors.md","filePath":"quant/obd-liquidity-common-factors.md","lastUpdated":1791063341000}'),m={name:"quant/obd-liquidity-common-factors.md"};function D(u,E,p,C,h,c){const t=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=i('<h1 id="流动性的共同因子" tabindex="-1">流动性的共同因子 <a class="header-anchor" href="#流动性的共同因子" aria-label="Permalink to &quot;流动性的共同因子&quot;">​</a></h1><div class="epigraph"><p>点差与深度不是各管各的：同一批做市资本服务着整面墙的名字——把共同变动从单票时序里拆出来，单票的流动性故事才讲得清。</p><footer>—— 据 Chordia, Roll and Subrahmanyam, Journal of Financial Economics, 2000；Bouchaud 等, Trades, Quotes and Prices, 2018 整理</footer></div><p><a href="/quant/obd-auction-microstructure">上一课</a>把竞价从连续段里分开；本课展开单元的横截面维度，把镜头从单票时间序列拉到整个市场：点差、深度、实现价差、毒性代理的共同变动。资产定价面主干已讲过<a href="/quant/liquidity-factor">流动性因子</a>与<a href="/quant/amihud-illiquidity">Amihud 非流动性</a>；本课在微观结构面板上做同一件事——提取共同因子，把单票流动性分解成因子、载荷与特异项。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单票点差的时序混杂两层：票面特质（事件、股东结构、注意度）与市场范围的流动性波动（资金面、波动体制、公告日）。不分离，上一课的毒性回归会把市场性收紧记成个股毒性上升，微观事件研究会把共同冲击当成处理效应。资产定价面的因子是日频、代理变量口径的；微观面板是日内、多变量的——把共同性做在高频口径上，才能回答「流动性收缩几点开始、先紧点差还是先掉深度」这类定价面答不了的问题。</p><p><span class="marginnote">术语翻译：流动性 beta 就是「你的票随大盘流动性动的放大倍数」——市场整体点差变宽 10%、你的票跟着变宽 15%，beta 约 1.5。它和收益 beta 一样是载荷，只是载在点差与深度上而不是收益上。</span></p><h3 id="测什么、怎么提" tabindex="-1">测什么、怎么提 <a class="header-anchor" href="#测什么、怎么提" aria-label="Permalink to &quot;测什么、怎么提&quot;">​</a></h3><p>面板的列是微观量：相对点差、各档深度、实现价差、成交强度、毒性代理；口径照第五课先对齐（交易时钟、去日内形状），再跨票标准化。提取用动态因子模型或 PCA，载荷就是流动性 beta。关键的经验约束是共同性的时变性：市场下跌与高波动时段共同性显著上升——载荷不是常数，全样本 PCA 会把危机样本的强共同性摊进整段历史，夸大第一主成分的常态占比。</p><p><span class="marginnote">进因子前把点差取对数：点差右偏、票间水平差大，直接用水平值，第一主成分会退化成「高价差票」的哑变量——提取出来的不是共同变动，是横截面分组的影子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程四步。口径：对齐与去季节照第五课，标准化在票内做（对数或稳健 z 分）。提取：小面板直接 PCA，时变载荷用动态因子或滚动窗；因子个数按截面平均相关的陡降判断，不硬凑。解释与验证：经济来源按三条核对——共同做市资本与资金约束（资金紧则全线收缩）、共同波动体制、共同公告；验证是因子极端日的事件回看：资金事件、大波动日是否落在因子尾部。下游接回：毒性回归加因子控制项，把市场性收紧从个股毒性里扣除；状态空间的噪声体制按因子状态切换。</p>',11)),(B(),o(n,null,{default:a(()=>[r(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PANEL%5B%22%E5%BE%AE%E8%A7%82%E7%BB%93%E6%9E%84%E9%9D%A2%E6%9D%BF%EF%BC%9A%E7%82%B9%E5%B7%AE%2F%E6%B7%B1%E5%BA%A6%2F%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%22%5D%20--%3E%20AL%5B%22%E5%AF%B9%E9%BD%90%20%2B%20%E5%8E%BB%E5%AD%A3%E8%8A%82%20%2B%20%E7%A5%A8%E5%86%85%E6%A0%87%E5%87%86%E5%8C%96%22%5D%0A%20%20AL%20--%3E%20PCA%5B%22%E5%8A%A8%E6%80%81%E5%9B%A0%E5%AD%90%2FPCA%20%E6%8F%90%E5%8F%96%22%5D%0A%20%20PCA%20--%3E%20F%5B%22%E5%85%B1%E5%90%8C%E6%B5%81%E5%8A%A8%E6%80%A7%E5%9B%A0%E5%AD%90%22%5D%0A%20%20PCA%20--%3E%20BETA%5B%22%E8%BD%BD%E8%8D%B7%EF%BC%9A%E6%B5%81%E5%8A%A8%E6%80%A7%20beta%22%5D%0A%20%20PCA%20--%3E%20IDIO%5B%22%E7%89%B9%E5%BC%82%E9%A1%B9%EF%BC%9A%E4%B8%AA%E8%82%A1%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20F%20--%3E%20DOWN%5B%22%E6%AF%92%E6%80%A7%E5%9B%9E%E5%BD%92%E6%8E%A7%E5%88%B6%20%2F%20%E4%BD%93%E5%88%B6%E5%88%87%E6%8D%A2%20%2F%20%E9%A2%84%E8%AD%A6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"共同性在供给侧：一批做市商、同一池资金、同一套风险约束服务所有名字，约束收紧时没有票独善其身——这是共同性的微观理由，也是它有宏观锚的原因。时变性在容量：常态下约束松、特质流主导、共同性弱；压力下容量绑定，共同性跳升。不完全共同在票面：事件、持仓集中度与特质流量让特异项有真实方差——这层不是噪声，是单票研究该留下的部分。",-1)),E[5]||(E[5]=A("p",null,"约束松紧如何决定共同性高低，是时变载荷的机制图：",-1)),(B(),o(n,null,{default:a(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E5%85%B1%E5%90%8C%E5%81%9A%E5%B8%82%E8%B5%84%E6%9C%AC%E4%B8%8E%E9%A3%8E%E9%99%A9%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20NORM%7B%22%E5%BD%93%E6%97%A5%E7%BA%A6%E6%9D%9F%E6%9D%BE%E7%B4%A7%22%7D%0A%20%20NORM%20--%3E%7C%22%E5%B8%B8%E6%80%81%3A%E5%AE%B9%E9%87%8F%E5%AF%8C%E4%BD%99%22%7C%20IDIO%5B%22%E7%89%B9%E8%B4%A8%E6%B5%81%E4%B8%BB%E5%AF%BC%2C%E5%90%84%E7%A5%A8%E5%90%84%E8%B5%B0%22%5D%0A%20%20NORM%20--%3E%7C%22%E5%8E%8B%E5%8A%9B%3A%E5%AE%B9%E9%87%8F%E7%BB%91%E5%AE%9A%22%7C%20TIGHT%5B%22%E5%85%A8%E7%BA%BF%E5%90%8C%E5%90%91%E6%94%B6%E7%BC%A9%22%5D%0A%20%20IDIO%20--%3E%20WEAK%5B%22%E5%85%B1%E5%90%8C%E6%80%A7%E5%BC%B1%3A%E8%BD%BD%E8%8D%B7%E4%BD%8E%22%5D%0A%20%20TIGHT%20--%3E%20STRONG%5B%22%E5%85%B1%E5%90%8C%E6%80%A7%E8%B7%B3%E5%8D%87%3A%E8%BD%BD%E8%8D%B7%E5%8D%87%22%5D%0A%20%20STRONG%20--%3E%20CHK%5B%22%E9%AA%8C%E8%AF%81%3A%E5%9B%A0%E5%AD%90%E6%9E%81%E7%AB%AF%E6%97%A5%E5%BA%94%E6%92%9E%E4%B8%8A%E8%B5%84%E9%87%91%2F%E6%B3%A2%E5%8A%A8%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20TIGHT%20--%3E%20TRAP%5B%22%E5%85%A8%E6%A0%B7%E6%9C%AC%20PCA%20%E4%BC%9A%E8%A2%AB%E5%8D%B1%E6%9C%BA%E6%A0%B7%E6%9C%AC%E7%BB%91%E6%9E%B6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">数字实例：常态下几十只票点差变化的截面平均相关可能只有 0.1 上下，资金紧的日子能冲到 0.5 以上；第一主成分解释的方差占比随之从不到两成跳到过半。把两类日子混进一个全样本 PCA，得到的「平均共同性」哪天都不像。</span></p><p>错法各有形状：用日频 ILLIQ 宣称微观结论（口径错配）；跨票直接平均原始点差（水平主导）；因子提完不复核极端日（只提了统计量，没验证含义）；把特异项当噪声平滑掉（丢掉单票研究的目标）。</p><p><span class="marginnote">常见误区：初学者容易以为流动性是单票属性——「我的票够活跃就行」。压力情景里要问的是：全市场同时收紧时，你的退出成本按流动性 beta 被整体抬升多少；约束是同一池资金给的，没有票独善其身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>微观数据的横截面覆盖有限：面板只含高频数据可得的名字，幸存与覆盖偏差进因子。共同性与市场收益双向：跌引起流动性收缩，收缩也压价格——因子模型不自动给出因果。载荷在制度变化处断裂：交易制度改、tick 变，beta 要重估。微观因子与定价面的流动性溢价对接要过频率与口径两道转换，本课的因子不直接就是风险价格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>微观结构面板上提共同因子：单票流动性 = 因子 + 载荷 + 特异，日频代理是它的低频投影。</li><li>先对齐、去季节、票内标准化（点差取对数），否则水平差异冒充共同变动。</li><li>共同性时变：压力时段跳升，载荷非常数，全样本 PCA 会被危机样本绑架。</li><li>机制锚在共同做市资本与容量约束；特异项是单票故事，不是噪声。</li><li>出处：Chordia, Roll and Subrahmanyam, <em>JFE</em>, 2000；Pástor and Stambaugh, <em>JPE</em>, 2003；Acharya and Pedersen, <em>JFE</em>, 2005；定价面综述见<a href="/quant/liquidity-factor">流动性因子</a>。</li></ul>',7))])}const P=l(m,[["render",D]]);export{b as __pageData,P as default};
